var LOCAL_A=["test","demo","user","sample","mock","fake","dev","trial","guest","ghost","pilot","alpha","beta","dummy","shadow","quiet","lucky","swift","nova","echo"];
var LOCAL_B=["fox","wolf","river","cloud","star","otter","falcon","maple","comet","tiger","raven","pine","dawn","koi","heron","lynx","moose","sparrow","reed","fern","node","byte","pixel","quartz","ember"];
function rndItem(a,r){ return a[Math.floor((r||Math.random)()*a.length)]; }
function genLocal(r){
  r=r||Math.random;
  var pat=Math.floor(r()*3);
  var a=rndItem(LOCAL_A,r), b=rndItem(LOCAL_B,r), n=Math.floor(r()*9000+100);
  if(pat===0) return a+"."+b;
  if(pat===1) return a+"_"+b+n;
  return b+n;
}
function genEmail(domain,r){ return genLocal(r)+"@"+(domain||"example.com"); }
function batch(n,domain){ var out=[]; for(var i=0;i<n;i++) out.push(genEmail(domain)); return out; }
var EXPORTS={ genLocal:genLocal, genEmail:genEmail, batch:batch };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FakeEmailForgePure = EXPORTS; }
